                    d33ket(7) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(8) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(9) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(10) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3
                    d33ket(11) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2
                    d33ket(12) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2
                    d33ket(13) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2
                    d33ket(14) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(15) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(16) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(17) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(18) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(19) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(20) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3
                    d33ket(21) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2
                    d33ket(22) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2
                    d33ket(23) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2
                    d33ket(24) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(25) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(26) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(27) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(28) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(29) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(30) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3
                    d33ket(31) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(32) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(33) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
