                    d33ket(36) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(37) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(38) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(39) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(40) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5*sqrt3
                    d33ket(41) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(42) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(43) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(44) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(45) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(46) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(47) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(48) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(49) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(50) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5*sqrt3
                    d33ket(51) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(52) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(53) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(54) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(55) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(56) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
