                    d33ket(58) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(59) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(60) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5*sqrt3
                    d33ket(61) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(62) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(63) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(64) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(65) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(66) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(67) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(68) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(69) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(70) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5*sqrt3
                    d33ket(71) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
