                    d33ket(73) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(74) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
