                    d33ket(78) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(79) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(80) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5*sqrt3
                    d33ket(81) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(82) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(83) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5
                    d33ket(84) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(85) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(86) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(87) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(88) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(89) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5
                    d33ket(90) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt5*sqrt3
                    d33ket(91) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3
                    d33ket(92) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3
                    d33ket(93) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3
                    d33ket(94) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3*sqrt5
                    d33ket(95) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3*sqrt5
                    d33ket(96) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3*sqrt5
                    d33ket(97) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3*sqrt5
                    d33ket(98) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3*sqrt5
                    d33ket(99) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3*sqrt5
                    d33ket(100) = ff_pair%d_coeff_alt(ff_pair%pair_loc(kl) + ket_loop)*twopi_5_2*sqrt5*sqrt3*sqrt5*sqrt3

                    bra_loop = 0

                    do i = 1, ijtop

                      bra_loop = bra_loop + 1

                      t_expon_ab = ff_pair%t_expon_ab(ff_pair%pair_loc(ij) + bra_loop)
                      t_expon_a = ff_pair%expon_a(ff_pair%pair_loc(ij) + bra_loop)
                      t_expon_b = ff_pair%expon_b(ff_pair%pair_loc(ij) + bra_loop)
                      t_inverse_expon_ab = 1.0_dp/t_expon_ab

                      dum = bbrrk + t_expon_a*t_expon_b*rab*t_inverse_expon_ab
                      t_expon_abcd_inverse = 1.0_dp/(t_expon_ab + t_expon_cd)
                      expe = exp(-dum)*sqrt(t_expon_abcd_inverse)
                      rho = t_expon_ab*t_expon_cd*t_expon_abcd_inverse

                      xa = (t_expon_a*res%coord_sh(ish, 1) + t_expon_b*res%coord_sh(jsh, 1))
                      ya = (t_expon_a*res%coord_sh(ish, 2) + t_expon_b*res%coord_sh(jsh, 2))
                      za = (t_expon_a*res%coord_sh(ish, 3) + t_expon_b*res%coord_sh(jsh, 3))

                      xa = xa*t_inverse_expon_ab
                      ya = ya*t_inverse_expon_ab
                      za = za*t_inverse_expon_ab

                      axak = t_expon_ab*(xa - res%coord_sh(ksh, 1))
                      ayak = t_expon_ab*(ya - res%coord_sh(ksh, 2))
                      azak = t_expon_ab*(za - res%coord_sh(ksh, 3))

                      axai = t_expon_ab*(xa - res%coord_sh(ish, 1))
                      ayai = t_expon_ab*(ya - res%coord_sh(ish, 2))
                      azai = t_expon_ab*(za - res%coord_sh(ish, 3))

                      c1x = bxbk + axak
                      c2x = t_expon_ab*bxbk
                      c3x = bxbi + axai
                      c4x = t_expon_cd*axai

                      c1y = bybk + ayak
                      c2y = t_expon_ab*bybk
                      c3y = bybi + ayai
                      c4y = t_expon_cd*ayai

