                        beta(1) = sum0

                        do m = 1, 40
                          p1(m) = 0.0D+00
                          p2(m) = 1.0D+00
                        end do

                        do kk = 1, 6

                          sum1 = 0.0D+00
                          sum2 = 0.0D+00

                          do 30 m = 1, 40

                            if (wgrid(m) .eq. 0.0d+00) goto 30

                            p0(m) = p1(m)
                            p1(m) = p2(m)
                            p2(m) = (rgrid(m) - alpha(kk))*p1(m) - beta(kk)*p0(m)
                            t = wgrid(m)*p2(m)*p2(m)
                            sum1 = sum1 + t
                            sum2 = sum2 + t*rgrid(m)

30                          continue

                            alpha(kk + 1) = sum2/sum1
                            beta(kk + 1) = sum1/sum0
                            sum0 = sum1

                          end do

                          ! End of RYSDS

                          ! Call to RYSGW

                          rts(1) = alpha(1)
                          wts(1) = 1.0D+00
                          wrk(7) = 0.0D+00
                          do 100 kk = 2, 7

                            rts(kk) = alpha(kk)
                            wrk(kk - 1) = sqrt(beta(kk))
                            wts(kk) = 0.0D+00

100                         continue

                            do 240 l = 1, 7

                              jj = 0

105                           do 110 m = l, 7
                                if (m .eq. 7) go to 120
                                if (abs(wrk(m)) .le. (1.0D-14)*(abs(rts(m)) + abs(rts(m + 1)))) go to 120
110                             continue

120                             dpp = rts(l)
                                if (m .eq. l) go to 240
                                jj = jj + 1

                                dg = (rts(l + 1) - dpp)/(2.0D+00*wrk(l))
                                dr = sqrt(dg*dg + 1.0D+00)
                                dg = rts(m) - dpp + wrk(l)/(dg + sign(dr, dg))
                                ds = 1.0D+00
                                dc = 1.0D+00
                                dpp = 0.0D+00
                                mml = m - l

                                do 200 ii = 1, mml

                                  mmii = m - ii
                                  df = ds*wrk(mmii)
                                  db = dc*wrk(mmii)
                                  if (abs(df) .lt. abs(dg)) go to 150
                                  dc = dg/df
                                  dr = sqrt(dc*dc + 1.0D+00)
                                  wrk(mmii + 1) = df*dr
                                  ds = 1.0D+00/dr
                                  dc = dc*ds
                                  go to 160
150                               ds = df/dg
                                  dr = sqrt(ds*ds + 1.0D+00)
                                  wrk(mmii + 1) = dg*dr
                                  dc = 1.0D+00/dr
                                  ds = ds*dc
160                               dg = rts(mmii + 1) - dpp
                                  dr = (rts(mmii) - dg)*ds + 2.0D+00*dc*db
                                  dpp = ds*dr
                                  rts(mmii + 1) = dg + dpp
                                  dg = dc*dr - db
                                  df = wts(mmii + 1)
                                  wts(mmii + 1) = ds*wts(mmii) + dc*df
                                  wts(mmii) = dc*wts(mmii) - ds*df

200                               continue

                                  rts(l) = rts(l) - dpp
                                  wrk(l) = dg
                                  wrk(m) = 0.0D+00
                                  go to 105

240                               continue

                                  do 300 ii = 2, 7

                                    iim1 = ii - 1
                                    kk = iim1
                                    dpp = rts(iim1)

