                                      if (rts(jj) .ge. dpp) go to 260
                                      kk = jj
                                      dpp = rts(jj)
260                                   continue

                                      if (kk .eq. iim1) go to 300

                                      rts(kk) = rts(iim1)
                                      rts(iim1) = dpp
                                      dpp = wts(iim1)
                                      wts(iim1) = wts(kk)
                                      wts(kk) = dpp

300                                   continue

