                                        yin(1792) = yin(1792) + dykl*yin(1791)
                                        zin(1792) = zin(1792) + dzkl*zin(1791)

                                        ! i3 = i4 = 1791
                                        ! nm = nm -1 =    5

                                        ! i4 = ib+kn(nm) = 1790

                                        xin(1791) = xin(1791) + dxkl*xin(1790)
                                        yin(1791) = yin(1791) + dykl*yin(1790)
                                        zin(1791) = zin(1791) + dzkl*zin(1790)

                                        ! i3 = i4 = 1790
                                        ! nm = nm -1 =    4

                                        ! i4 = ib+kn(nm) = 1789

                                        xin(1790) = xin(1790) + dxkl*xin(1789)
                                        yin(1790) = yin(1790) + dykl*yin(1789)
                                        zin(1790) = zin(1790) + dzkl*zin(1789)

                                        ! i3 = i4 = 1789
                                        ! nm = nm -1 =    3

                                        ! end do

                                        ! min = min + 1 =    4

                                        ! nm = (kang+lang) =    6

                                        ! i3 = ib+i5 = 1792

                                        ! do while nm.gt.min

                                        ! i4 = ib+kn(nm) = 1791

                                        xin(1792) = xin(1792) + dxkl*xin(1791)
                                        yin(1792) = yin(1792) + dykl*yin(1791)
                                        zin(1792) = zin(1792) + dzkl*zin(1791)

                                        ! i3 = i4 = 1791
                                        ! nm = nm -1 =    5

                                        ! i4 = ib+kn(nm) = 1790

                                        xin(1791) = xin(1791) + dxkl*xin(1790)
                                        yin(1791) = yin(1791) + dykl*yin(1790)
                                        zin(1791) = zin(1791) + dzkl*zin(1790)

                                        ! i3 = i4 = 1790
                                        ! nm = nm -1 =    4

                                        ! end do

                                        ! min = min + 1 =    5

                                        ! nm = (kang+lang) =    6

                                        ! i3 = ib+i5 = 1792

                                        ! do while nm.gt.min

                                        ! i4 = ib+kn(nm) = 1791

                                        xin(1792) = xin(1792) + dxkl*xin(1791)
                                        yin(1792) = yin(1792) + dykl*yin(1791)
                                        zin(1792) = zin(1792) + dzkl*zin(1791)

                                        ! i3 = i4 = 1791
                                        ! nm = nm -1 =    5

                                        ! end do

                                        ! min = min + 1 =    6

                                        ! end do

                                        ! i3 = ib + 1 = 1778

                                        ! do nl = 1,    3

                                        ! i4 = i3 = 1778

                                        ! do nk = 1,    3

                                        xin(1778) = xin(1781) + dxkl*xin(1777)
                                        yin(1778) = yin(1781) + dykl*yin(1777)
                                        zin(1778) = zin(1781) + dzkl*zin(1777)
                                        ! i4 = i4 + lang+1 = 1782

                                        ! nk =    2

                                        xin(1782) = xin(1785) + dxkl*xin(1781)
                                        yin(1782) = yin(1785) + dykl*yin(1781)
                                        zin(1782) = zin(1785) + dzkl*zin(1781)
                                        ! i4 = i4 + lang+1 = 1786

                                        ! nk =    3

                                        xin(1786) = xin(1789) + dxkl*xin(1785)
                                        yin(1786) = yin(1789) + dykl*yin(1785)
                                        zin(1786) = zin(1789) + dzkl*zin(1785)
                                        ! i4 = i4 + lang+1 = 1790

                                        ! nk =    4

                                        ! end do

                                        ! i3 = i3 + 1 = 1779

                                        ! nl =    2

                                        ! i4 = i3 = 1779

                                        ! do nk = 1,    3

                                        xin(1779) = xin(1782) + dxkl*xin(1778)
                                        yin(1779) = yin(1782) + dykl*yin(1778)
                                        zin(1779) = zin(1782) + dzkl*zin(1778)
                                        ! i4 = i4 + lang+1 = 1783

                                        ! nk =    2

                                        xin(1783) = xin(1786) + dxkl*xin(1782)
                                        yin(1783) = yin(1786) + dykl*yin(1782)
                                        zin(1783) = zin(1786) + dzkl*zin(1782)
                                        ! i4 = i4 + lang+1 = 1787

                                        ! nk =    3

                                        xin(1787) = xin(1790) + dxkl*xin(1786)
                                        yin(1787) = yin(1790) + dykl*yin(1786)
                                        zin(1787) = zin(1790) + dzkl*zin(1786)
                                        ! i4 = i4 + lang+1 = 1791

                                        ! nk =    4

                                        ! end do

                                        ! i3 = i3 + 1 = 1780

                                        ! nl =    3

                                        ! i4 = i3 = 1780

                                        ! do nk = 1,    3

                                        xin(1780) = xin(1783) + dxkl*xin(1779)
                                        yin(1780) = yin(1783) + dykl*yin(1779)
                                        zin(1780) = zin(1783) + dzkl*zin(1779)
                                        ! i4 = i4 + lang+1 = 1784

                                        ! nk =    2

                                        xin(1784) = xin(1787) + dxkl*xin(1783)
                                        yin(1784) = yin(1787) + dykl*yin(1783)
                                        zin(1784) = zin(1787) + dzkl*zin(1783)
                                        ! i4 = i4 + lang+1 = 1788

                                        ! nk =    3

                                        xin(1788) = xin(1791) + dxkl*xin(1787)
                                        yin(1788) = yin(1791) + dykl*yin(1787)
                                        zin(1788) = zin(1791) + dzkl*zin(1787)
                                        ! i4 = i4 + lang+1 = 1792

                                        ! nk =    4

                                        ! end do

                                        ! i3 = i3 + 1 = 1781

                                        ! nl =    4

                                        ! end do

                                        ! ib = ib + (kang+1)*(lang+1) = 1793

                                        ! nj = nj + 1 =    4

                                        ! end do

                                        ! ni = ni + 1 =    4

                                        ! iaa = iaa + (jang+1)*(kang+1)*(lang+1) = 1793

                                        ! end do

                                        ! *** Now root =    8

                                        ! mm = mm + (iang+1)*(jang+2)*(kang+1)*(lang+1) = 1792

                                        !                     --- END XYZINT ---

                                        !                       --- FORMS ---
                                        ! Form final integrals adding the 2D auxiliaries over all roots

                                        j = 1

                                        do n = 1, 10000! loop over all integrals

                                          l = n - 100*(j - 1) ! index for the ket cartesian pair

                                          mx = ijx(j) + klx(l)
                                          my = ijy(j) + kly(l)
                                          mz = ijz(j) + klz(l)

                                          eri_value(n) = eri_value(n) + d33bra(j)*d33ket(l)* &
                                                         (xin(mx)*yin(my)*zin(mz) & ! root  1
                                                          + xin(mx + 256)*yin(my + 256)*zin(mz + 256) & ! root  2
                                                          + xin(mx + 512)*yin(my + 512)*zin(mz + 512) & ! root  3
                                                          + xin(mx + 768)*yin(my + 768)*zin(mz + 768) & ! root  4
                                                          + xin(mx + 1024)*yin(my + 1024)*zin(mz + 1024) & ! root  5
                                                          + xin(mx + 1280)*yin(my + 1280)*zin(mz + 1280) & ! root  6
                                                          + xin(mx + 1536)*yin(my + 1536)*zin(mz + 1536)) ! root  7

                                          j = int(n/100) + 1 ! index for the next bra cartesian pair

                                        end do

                                        !                     --- END FORMS ---

                                      end do ! ij primitve loop

                                    end do ! kl primitve loop

                                    !                     --- DIRFCK_RHF ---
                                    !          Compute Fock matrix elements from 2EIs

                                    maxj2 = 10
                                    iandj = ish .eq. jsh
                                    maxl = 10
                                    kandl = ksh .eq. lsh
                                    same = (ish .eq. ksh) .and. (jsh .eq. lsh)

                                    loci = res%atom_loc(ish) - 1
                                    locj = res%atom_loc(jsh) - 1
                                    lock = res%atom_loc(ksh) - 1
                                    locl = res%atom_loc(lsh) - 1

                                    nij = 0

                                    do i = 1, 10 ! # of cartesians in i

                                      if (iandj) maxj2 = i

                                      ii1 = i + loci
                                      ip = (i - 1)*1000 ! Stride between functions in i

                                      do j = 1, maxj2

                                        nij = nij + 1

                                        maxl2 = maxl

                                        jj1 = j + locj
                                        i2 = ii1
                                        j2 = jj1
                                        if (ii1 .lt. jj1) then ! Sort <ij|
                                          i2 = jj1
                                          j2 = ii1
                                        end if

                                        ijp = (j - 1)*100 + ip ! Add stride between functions in j

                                        nkl = nij

                                        do k = 1, 10 ! # of cartesians in k

                                          if (kandl) maxl2 = k

                                          kk1 = k + lock

                                          ijkp = (k - 1)*10 + ijp ! Add stride between functions in k

                                          if (same) then ! Account for non-unique permutations
                                            itmp = min(maxl2 - 1 + 1, nkl)
                                            if (itmp .eq. 0) exit ! Move to the next j iteration
                                            maxl2 = 1 + itmp - 1
                                            nkl = nkl - itmp
                                          end if

                                          do l = 1, maxl2

                                            ijklp = ijkp + l ! No stride between functions in l

                                            buff(1) = eri_value(ijklp)

                                            if (abs(buff(1)) .lt. 5.0D-11) cycle ! Skip small integrals

                                            ll1 = l + locl
                                            k2 = kk1
                                            l2 = ll1

                                            if (k2 .lt. l2) then ! sort |kl>
                                              k2 = ll1
                                              l2 = kk1
                                            end if

                                            ii = i2
                                            jj = j2
                                            kk = k2
                                            ll = l2

                                            if (ii .lt. kk) then ! sort <ij|kl>
                                              ii = k2
                                              jj = l2
                                              kk = i2
                                              ll = j2

                                            else if (ii .eq. kk .and. jj .lt. ll) then ! sort <ij|il>
                                              jj = l2
                                              ll = j2
                                            end if

                                            ii2 = res%ia(ii)
                                            jj2 = res%ia(jj)
                                            kk2 = res%ia(kk)

                                            ij = ii2 + jj
                                            ik = ii2 + kk
                                            il = ii2 + ll
                                            jk = jj2 + kk
                                            jl = jj2 + ll
                                            kl = kk2 + ll

                                            if (jj .lt. kk) jk = kk2 + jj
                                            if (jj .lt. ll) jl = res%ia(ll) + jj

                                            ! Account for identical permutations

                                            if (ii .eq. jj) buff(1) = buff(1)*0.5_dp
                                            if (kk .eq. ll) buff(1) = buff(1)*0.5_dp
                                            if (ii .eq. kk .and. jj .eq. ll) buff(1) = buff(1)*0.5_dp

                                            buff(2) = buff(1)
                                            buff(3) = buff(1)*4.0_dp

                                            buff(4) = buff(3)*density(kl)
                                            buff(5) = buff(3)*density(ij)
                                            buff(6) = -buff(2)*density(jl)
                                            buff(7) = -buff(2)*density(ik)
                                            buff(8) = -buff(2)*density(jk)
                                            buff(9) = -buff(2)*density(il)

                                            !$omp atomic update
                                            fock(ij) = fock(ij) + buff(4)
                                            !$omp atomic update
                                            fock(kl) = fock(kl) + buff(5)
                                            !$omp atomic update
                                            fock(ik) = fock(ik) + buff(6)
                                            !$omp atomic update
                                            fock(jl) = fock(jl) + buff(7)
                                            !$omp atomic update
                                            fock(il) = fock(il) + buff(8)
                                            !$omp atomic update
                                            fock(jk) = fock(jk) + buff(9)

                                          end do ! l
                                        end do ! k
                                      end do ! j
                                    end do ! i

                                    !                  --- END DIRFCK_RHF ---

                                  end do ! kkll - or single loop for Do Concurrent

                              end do ! iijj
                              !$omp end target teams distribute parallel do


                              deallocate (n33bra)
                              deallocate (xint33bra)

                              end subroutine int3333
                              end submodule
